      if (body.leg != null && !["L", "R"].includes(String(body.leg))) return r({ error: "leg_must_be_L_or_R" }, 400);
      const { data: c } = await supabase.from("contacts").select("id").eq("id", contactId).eq("user_id", ownerId).maybeSingle();
